{"file_path":"src/cli.js","content":"import { parseDocument, ParseError } from './parser.js'
import { renderJson, renderKeys } from './render.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const chunks = []
for await (const c of process.stdin) chunks.push(c)
const text = Buffer.concat(chunks).toString('utf8')

try {
  const root = parseDocument(text)
  process.stdout.write(mode === 'json' ? renderJson(root) : renderKeys(root))
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
  process.exitCode = 2
}
"}

{"file_path":"src/render.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

const sortedKeys = (t) => [...t.m.keys()].sort(cmp)

function scalar(n) {
  switch (n.t) {
    case 'string': return JSON.stringify(n.v)
    case 'boolean': return n.v ? 'true' : 'false'
    case 'integer': return n.v.toString()
    default: return JSON.stringify(n.v)
  }
}

function json(n, ind) {
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    const pad = '  '.repeat(ind + 1)
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + json(n.m.get(k), ind + 1)).join(',\n') + '\n' + '  '.repeat(ind) + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    const pad = '  '.repeat(ind + 1)
    return '[\n' + n.items.map((i) => pad + json(i, ind + 1)).join(',\n') + '\n' + '  '.repeat(ind) + ']'
  }
  return scalar(n)
}

export const renderJson = (root) => json(root, 0) + '\n'

export function renderKeys(root) {
  const out = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n)) {
        const p = path === null ? k : path + '.' + k
        out.push(`${p} ${n.m.get(k).t}`)
        walk(n.m.get(k), p)
      }
    } else if (n.t === 'array') {
      n.items.forEach((it, i) => {
        const p = `${path}[${i}]`
        out.push(`${p} ${it.t}`)
        walk(it, p)
      })
    }
  }
  walk(root, null)
  return out.length ? out.join('\n') + '\n' : ''
}
"}

{"file_path":"src/parser.js","content":"export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const newTable = () => ({ t: 'table', m: new Map(), made: false })

class LineParser {
  constructor(s, line) {
    this.s = s
    this.i = 0
    this.line = line
  }
  fail(msg) {
    throw new ParseError(msg, this.line)
  }
  peek() {
    return this.s[this.i]
  }
  ws() {
    while (isWs(this.s[this.i])) this.i++
  }
  // at end of the meaningful text (end of line or a comment)
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }

  name() {
    const c = this.peek()
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    if (!isNameChar(c)) this.fail('expected a name')
    const st = this.i
    while (isNameChar(this.s[this.i])) this.i++
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else {
        this.i = save
        break
      }
    }
    return names
  }

  basic() {
    this.i++
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) this.fail('unterminated string')
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        const e = this.s[this.i + 1]
        if (e === undefined) this.fail('unterminated string')
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) {
          out += map[e]
          this.i += 2
        } else if (e === 'u') {
          const h = this.s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 6
        } else {
          const cp = String.fromCodePoint(this.s.codePointAt(this.i + 1))
          this.fail('invalid escape \\' + cp)
        }
      } else {
        out += c
        this.i++
      }
    }
  }

  literal() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) this.fail('unterminated string')
    const v = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return v
  }

  value(base) {
    this.ws()
    const c = this.peek()
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    const f = new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`)
    if (f.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    this.fail('invalid value ' + w)
  }

  array(base) {
    this.i++
    const items = []
    this.ws()
    if (this.peek() === ']') {
      this.i++
      return { t: 'array', aot: false, items }
    }
    for (;;) {
      items.push(this.value(base))
      this.ws()
      const c = this.peek()
      if (c === ',') {
        this.i++
        this.ws()
        if (this.peek() === ']') {
          this.i++
          break
        }
      } else if (c === ']') {
        this.i++
        break
      } else if (this.atEnd()) this.fail('unterminated array')
      else this.fail('trailing text after a value')
    }
    return { t: 'array', aot: false, items }
  }

  inline(base) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.peek() === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      const names = this.dotted()
      this.ws()
      if (this.peek() !== '=') this.fail('expected = in an inline table')
      this.i++
      const v = this.value(base)
      assign(this, tbl, base, names, v)
      this.ws()
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === '}') {
        this.i++
        break
      } else if (this.atEnd()) this.fail('unterminated inline table')
      else this.fail('trailing text after a value')
    }
    return tbl
  }
}

// Walk the intermediate names, creating tables; returns the table reached.
function walk(p, table, prefix, names) {
  let cur = table
  const path = [...prefix]
  for (const n of names) {
    path.push(n)
    let ch = cur.m.get(n)
    if (!ch) {
      ch = newTable()
      cur.m.set(n, ch)
    }
    if (ch.t === 'array' && ch.aot) ch = ch.items[ch.items.length - 1]
    else if (ch.t !== 'table') p.fail(`${path.join('.')} is not a table`)
    cur = ch
  }
  return { table: cur, path }
}

function assign(p, table, prefix, names, value) {
  const { table: t, path } = walk(p, table, prefix, names.slice(0, -1))
  const k = names[names.length - 1]
  path.push(k)
  if (t.m.has(k)) p.fail(`key ${path.join('.')} is defined twice`)
  t.m.set(k, value)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((raw, idx) => {
    const p = new LineParser(raw, idx + 1)
    p.ws()
    const c = p.peek()
    if (c === undefined || c === '#' || c === ';') return
    if (c === '[') {
      p.i++
      const aot = p.peek() === '['
      if (aot) p.i++
      p.ws()
      const names = p.dotted()
      p.ws()
      const close = aot ? ']]' : ']'
      if (p.s.startsWith(close, p.i)) p.i += close.length
      else if (p.i >= p.s.length || p.atEnd()) p.fail('unterminated table header')
      else p.fail('trailing text after a table header')
      p.ws()
      if (!p.atEnd()) p.fail('trailing text after a table header')
      const { table: parent, path } = walk(p, root, [], names.slice(0, -1))
      const k = names[names.length - 1]
      path.push(k)
      const ps = path.join('.')
      const ex = parent.m.get(k)
      if (aot) {
        if (!ex) {
          const t = newTable()
          parent.m.set(k, { t: 'array', aot: true, items: [t] })
          cur = t
        } else if (ex.t === 'array' && ex.aot) {
          const t = newTable()
          ex.items.push(t)
          cur = t
        } else p.fail(`${ps} is not an array of tables`)
      } else {
        if (!ex) {
          const t = newTable()
          t.made = true
          parent.m.set(k, t)
          cur = t
        } else if (ex.t === 'table') {
          if (ex.made) p.fail(`table ${ps} is defined twice`)
          ex.made = true
          cur = ex
        } else p.fail(`${ps} is not a table`)
      }
      curPath = path
      return
    }
    const names = p.dotted()
    p.ws()
    if (p.peek() !== '=') p.fail('expected key = value')
    p.i++
    const v = p.value(curPath)
    p.ws()
    if (!p.atEnd()) p.fail('trailing text after a value')
    assign(p, cur, curPath, names, v)
  })
  return root
}
"}

