#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function isInt(s, least) {
  return UINT.test(s) && BigInt(s) >= BigInt(least)
}

class Bucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.cap = capacity * per
    this.refill = refill
    this.per = per
    this.state = new Map()
  }
  advance(key, tick) {
    let s = this.state.get(key)
    if (!s) {
      s = { num: this.cap, last: tick }
      this.state.set(key, s)
      return
    }
    s.num += this.refill * (tick - s.last)
    if (s.num > this.cap) s.num = this.cap
    s.last = tick
  }
  allows(key) {
    return this.state.get(key).num >= this.per
  }
  record(key) {
    this.state.get(key).num -= this.per
  }
}

class Window {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.state = new Map()
  }
  advance(key, tick) {
    let s = this.state.get(key)
    if (!s) {
      s = []
      this.state.set(key, s)
    }
    const edge = tick - this.span
    while (s.length && s[0] <= edge) s.shift()
  }
  allows(key) {
    return BigInt(this.state.get(key).length) < this.limit
  }
  record(key, tick) {
    this.state.get(key).push(tick)
  }
}

function process_(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const fail = (m) => new Fail(`line ${i + 1}: ${m}`)
    const d = t[0]
    if (d === 'bucket' || d === 'window') {
      const isB = d === 'bucket'
      if (t.length !== (isB ? 5 : 4)) {
        throw fail(isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      }
      if (started) throw fail('declarations must come before the first event')
      if (!NAME.test(t[1])) throw fail(`invalid policy name ${t[1]}`)
      const fields = isB
        ? [['capacity', 1], ['refill', 0], ['per', 1]]
        : [['limit', 0], ['span', 1]]
      fields.forEach(([f, least], j) => {
        if (!isInt(t[2 + j], least)) throw fail(`${f} must be an integer of at least ${least}`)
      })
      if (policies.has(t[1])) throw fail(`policy ${t[1]} is declared twice`)
      const n = t.slice(2).map(BigInt)
      policies.set(t[1], isB ? new Bucket(t[1], n[0], n[1], n[2]) : new Window(t[1], n[0], n[1]))
    } else if (d === 'route') {
      if (t.length < 3) throw fail('expected route <prefix> <policy>...')
      if (started) throw fail('declarations must come before the first event')
      if (!NAME.test(t[1])) throw fail(`invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) throw fail(`prefix ${t[1]} is routed twice`)
      const list = t.slice(2).map((p) => {
        if (!policies.has(p)) throw fail(`unknown policy ${p}`)
        return policies.get(p)
      })
      routes.set(t[1], list)
    } else if (d === 'event') {
      if (t.length !== 3) throw fail('expected event <tick> <key>')
      if (!isInt(t[1], 0)) throw fail('tick must be an integer of at least 0')
      if (!NAME.test(t[2])) throw fail(`invalid key ${t[2]}`)
      const tick = BigInt(t[1])
      if (lastTick !== null && tick < lastTick) throw fail(`tick ${t[1]} is before tick ${lastTick}`)
      lastTick = tick
      started = true
      events.push({ tick, key: t[2] })
    } else {
      throw fail(`unknown directive ${d}`)
    }
  }
  const out = []
  const counts = new Map()
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const p of routes.keys()) {
      if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
    }
    let refused = null
    if (best !== null) {
      const list = routes.get(best)
      for (const p of list) p.advance(key, tick)
      for (const p of list) {
        if (!p.allows(key)) {
          refused = p
          break
        }
      }
      if (!refused) for (const p of list) p.record(key, tick)
    }
    const c = counts.get(key) || { a: 0, d: 0 }
    counts.set(key, c)
    if (refused) {
      c.d++
      td++
      out.push(`${tick} ${key} deny ${refused.name}`)
    } else {
      c.a++
      ta++
      out.push(`${tick} ${key} allow`)
    }
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  const keys = [...counts.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))
  return keys.map((k) => `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}\n`).join('') +
    `total allowed=${ta} denied=${td}\n`
}

let result
try {
  result = process_(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(result)
EOF
