  if (n === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const v = toNum(ev(args[0]))
    return v.t === 'e' ? v : num(Math.abs(v.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(n)) return err('#NAME?')
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.n === 'range') {
      const cs = rangeCells(a)
      if (!cs) vals.push(err('#REF!'))
      else for (const c of cs) vals.push(cellValue(c.key))
    } else vals.push(ev(a))
  }
  const first = vals.find((v) => v.t === 'e')
  if (first) return first
  if (n === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const ns = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    ns.push(x.v)
  }
  if (n === 'SUM') return fin(ns.reduce((a, b) => a + b, 0))
  if (n === 'AVG') return fin(ns.reduce((a, b) => a + b, 0) / ns.length)
  if (n === 'MIN') return fin(ns.reduce((a, b) => (b < a ? b : a)))
  return fin(ns.reduce((a, b) => (b > a ? b : a)))
}

function fmt(v) {
  if (v.t === 'n') return String(Number(v.v.toPrecision(10)))
  if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
  return String(v.v)
}

const sorted = [...cells.values()].sort((x, y) => x.a.col - y.a.col || x.a.row - y.a.row)
let out = ''
for (const cell of sorted) {
  if (mode === 'values') out += `${cell.a.key}=${fmt(cellValue(cell.a.key))}\n`
  else {
    const refs = new Map()
    if (cell.content[0] === '=') {
      const ast = getParsed(cell)
      if (ast) refsOf(ast, refs)
    }
    const list = [...refs.values()].sort((x, y) => x.col - y.col || x.row - y.row)
    out += `${cell.a.key}:${list.map((r) => ' ' + r.key).join('')}\n`
  }
}
