      let s = ''
      const take = () => { s += adv() }
      // digit run with single underscores between digits
      const run = (pred) => {
        let any = false
        while (i < n) {
          if (pred(cs[i])) { take(); any = true }
          else if (cs[i] === '_' && any && pred(cs[i - 1]) && pred(cs[i + 1])) take()
          else break
        }
