        if (!run(pred)) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { take(); run(isDigit) }
        if ((cs[i] === 'e' || cs[i] === 'E') &&
          (isDigit(cs[i + 1]) || ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])))) {
          take()
          if (!isDigit(cs[i])) take()
          run(isDigit)
        }
      }
