const RE = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/

export function parse(s) {
  const m = RE.exec(s)
  const u = { scheme: m[1], authority: undefined, path: m[3], query: m[4], fragment: m[5] }
  if (m[2] !== undefined) {
    const a = m[2]
    const at = a.lastIndexOf('@')
    const userinfo = at >= 0 ? a.slice(0, at) : undefined
    const hp = at >= 0 ? a.slice(at + 1) : a
    const colon = hp.indexOf(':', hp.lastIndexOf(']') + 1)
    u.authority = {
      userinfo,
      host: colon >= 0 ? hp.slice(0, colon) : hp,
      port: colon >= 0 ? hp.slice(colon + 1) : undefined,
    }
  }
  return u
}

export function checkPercent(u) {
  const bad = /%(?![0-9A-Fa-f]{2})/
  const parts = [
    ['path', u.path],
    ['userinfo', u.authority && u.authority.userinfo],
    ['host', u.authority && u.authority.host],
    ['query', u.query],
    ['fragment', u.fragment],
  ]
  for (const [name, v] of parts) if (v !== undefined && bad.test(v)) return name
  return null
}

function pct(s) {
  if (s === undefined) return s
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

const asciiLower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function removeDots(path) {
  let inp = path
  const out = []
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../')) { inp = inp.slice(3); out.pop() }
    else if (inp === '/..') { inp = '/'; out.pop() }
    else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out.push(seg)
      inp = inp.slice(seg.length)
    }
  }
  return out.join('')
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function normalize(u) {
  const scheme = u.scheme === undefined ? undefined : asciiLower(u.scheme)
  let auth
  if (u.authority) {
    let port = u.authority.port
    if (port === '' || (scheme && DEFAULT_PORT[scheme] === port)) port = undefined
    auth = {
      userinfo: pct(u.authority.userinfo),
      host: asciiLower(pct(u.authority.host)),
      port: pct(port),
    }
  }
  let path = removeDots(pct(u.path))
  if (auth && path === '') path = '/'
  return { scheme, authority: auth, path, query: pct(u.query), fragment: pct(u.fragment) }
}

