  let s = ''
  if (u.scheme !== undefined) s += u.scheme + ':'
  if (u.authority) {
    s += '//'
    if (u.authority.userinfo !== undefined) s += u.authority.userinfo + '@'
    s += u.authority.host
    if (u.authority.port !== undefined) s += ':' + u.authority.port
  }
  s += u.path
  if (u.query !== undefined) s += '?' + u.query
  if (u.fragment !== undefined) s += '#' + u.fragment
  return s
}

