import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function diff(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const changes = []
  let i = 0, j = 0, cur = null
  const flush = () => { if (cur) { changes.push(cur); cur = null } }
  const open = () => { if (!cur) cur = { bs: i, be: i, ss: j, se: j } }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) { flush(); i++; j++; continue }
    open()
    if (j >= m || (i < n && L[i + 1][j] >= L[i][j + 1])) i++
    else j++
    cur.be = i; cur.se = j
  }
  flush()
  return changes
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function merge(mine, base, theirs) {
  const all = [
    ...diff(base, mine).map(c => ({ ...c, side: 0 })),
    ...diff(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)
  const docs = [mine, theirs]
  const out = []
  let pos = 0, k = 0
  while (k < all.length) {
    if (all[k].bs > pos) out.push({ kind: 'stable', lines: base.slice(pos, all[k].bs) })
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    pos = re
    if (group.length === 1) {
      const c = group[0]
      out.push({ kind: c.side ? 'theirs' : 'mine', lines: docs[c.side].slice(c.ss, c.se) })
      continue
    }
    const repl = side => {
      const cs = group.filter(c => c.side === side)
      if (!cs.length) return base.slice(rs, re)
      const s = Math.min(...cs.map(c => c.bs)), e = Math.max(...cs.map(c => c.be))
      const ss = Math.min(...cs.map(c => c.ss)), se = Math.max(...cs.map(c => c.se))
      return docs[side].slice(ss - (s - rs), se + (re - e))
    }
    const m = repl(0), t = repl(1), b = base.slice(rs, re)
    if (eq(m, t)) out.push({ kind: 'both', lines: m })
    else if (eq(m, b)) out.push({ kind: 'theirs', lines: t })
    else if (eq(t, b)) out.push({ kind: 'mine', lines: m })
    else out.push({ kind: 'conflict', mine: m, base: b, theirs: t })
  }
  if (pos < base.length) out.push({ kind: 'stable', lines: base.slice(pos) })
  return out
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (!['merge', 'merge2', 'regions'].includes(mode)) fail('usage: cli.js merge|merge2|regions')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) {
  if (l === '%%%') docs.push([])
  else docs[docs.length - 1].push(l)
}
if (docs.length !== 3) fail('expected three parts separated by %%%')

const regions = merge(docs[0], docs[1], docs[2])
const res = []
let conflict = false
for (const r of regions) {
  if (r.kind === 'conflict') {
    conflict = true
    if (mode === 'regions') res.push(`conflict mine=${r.mine.length} base=${r.base.length} theirs=${r.theirs.length}`)
    else {
      res.push('<<<<<<< mine', ...r.mine)
      if (mode === 'merge') res.push('||||||| base', ...r.base)
      res.push('=======', ...r.theirs, '>>>>>>> theirs')
    }
  } else if (mode === 'regions') res.push(`${r.kind} ${r.lines.length}`)
  else res.push(...r.lines)
}
process.stdout.write(res.map(l => l + '\n').join(''))
process.exitCode = conflict ? 1 : 0
EOF
