"}

{"file_path":"src/parse.js","content":"/** Parses election text into { candidates, ballots: [{count: bigint, ranking}] }. */
function bad(message) {
  const e = new Error(message)
  e.election = true
  return e
}

const NAME = /^[A-Za-z0-9_-]+$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const words = line.split(/\s+/)
    const word = words[0]
    if (word === 'candidates') {
      if (candidates !== null) throw bad(`line ${n}: candidates must be declared once, before any ballot`)
      if (words.length < 2) throw bad(`line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of words.slice(1)) {
        if (!NAME.test(name)) throw bad(`line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) throw bad(`line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = [...seen]
    } else if (word === 'ballot') {
      if (candidates === null) throw bad(`line ${n}: candidates must be declared once, before any ballot`)
      if (words.length < 3) throw bad(`line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(words[1])) throw bad(`line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of words.slice(2)) {
        if (!candidates.includes(name)) throw bad(`line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) throw bad(`line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(words[1]), ranking: words.slice(2) })
    } else {
      throw bad(`line ${n}: unknown directive ${word}`)
    }
  })
  if (candidates === null) throw bad('no candidates')
  return { candidates, ballots }
}
"}

{"file_path":"src/count.js","content":"/** Runs the instant-runoff count. */
export function count({ candidates, ballots }) {
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  let continuing = [...candidates]
  const history = [] // history[r] = Map name -> votes
  const lines = []
  for (;;) {
    const votes = new Map(continuing.map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const pick = b.ranking.find((c) => votes.has(c))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    history.push(votes)
    const rounds = history.length
    const listed = [...continuing].sort((a, b) => {
      const d = votes.get(b) - votes.get(a)
      if (d !== 0n) return d > 0n ? 1 : -1
      return a < b ? -1 : a > b ? 1 : 0
    })
    let line = `round ${rounds}: ${listed.map((c) => `${c}=${votes.get(c)}`).join(' ')} exhausted=${total - active}`
    lines.push(line)
    if (active === 0n) return { lines, rounds, winner: null }
    const winner = continuing.find((c) => votes.get(c) * 2n > active)
    if (winner !== undefined) return { lines, rounds, winner }

    let min = null
    for (const c of continuing) if (min === null || votes.get(c) < min) min = votes.get(c)
    let set = continuing.filter((c) => votes.get(c) === min)
    let r = 0
    while (set.length > 1 && r < history.length) {
      let lo = null
      let allEqual = true
      for (const c of set) {
        const v = history[r].get(c)
        if (lo !== null && v !== lo) allEqual = false
        if (lo === null || v < lo) lo = v
      }
      if (allEqual) r++
      else {
        set = set.filter((c) => history[r].get(c) === lo)
        r = 0
      }
    }
    const out = set.reduce((a, b) => (b > a ? b : a))
    lines.push(`eliminated ${out}`)
    continuing = continuing.filter((c) => c !== out)
  }
}
"}

