function changes(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const res = []
  let i = 0, j = 0, cur = null
  const flush = () => { if (cur) { res.push(cur); cur = null } }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) { flush(); i++; j++; continue }
    if (!cur) cur = { bs: i, be: i, ss: j, se: j }
    if (j >= m || (i < n && L[i + 1][j] >= L[i][j + 1])) { i++; cur.be = i } else { j++; cur.se = j }
  }
  flush()
  return res
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mine, base, theirs) {
  const all = [
    ...changes(base, mine).map(c => ({ ...c, side: 0 })),
    ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)
  const regions = []
  let conflict = false, pos = 0, k = 0
  const docs = [mine, theirs]
  while (k < all.length) {
    const start = all[k].bs
    let end = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= end) {
      end = Math.max(end, all[k].be)
      group.push(all[k++])
    }
    if (start > pos) regions.push({ kind: 'stable', lines: base.slice(pos, start) })
    pos = end
    const rep = s => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return base.slice(start, end)
      const first = cs[0], last = cs[cs.length - 1]
      const minBs = Math.min(...cs.map(c => c.bs)), maxBe = Math.max(...cs.map(c => c.be))
      const a = first.ss - (minBs - start)
      const b = last.se + (end - maxBe)
      return docs[s].slice(a, b)
    }
    const m = rep(0), t = rep(1), b = base.slice(start, end)
    if (eq(m, t)) regions.push({ kind: 'both', lines: m })
    else if (eq(m, b)) regions.push({ kind: 'theirs', lines: t })
    else if (eq(t, b)) regions.push({ kind: 'mine', lines: m })
    else { conflict = true; regions.push({ kind: 'conflict', mine: m, base: b, theirs: t }) }
  }
