{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const f = line.split(/\s+/)
    const fail = (m) => { throw new Fail(`line ${i + 1}: ${m}`) }
    const int = (field, v, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = f[0]
    if (!['bucket', 'window', 'route', 'event'].includes(d)) fail(`unknown directive ${d}`)
    if (d !== 'event' && events.length) fail('declarations must come before the first event')
    if (d === 'bucket') {
      if (f.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
      if (!NAME.test(f[1])) fail(`invalid policy name ${f[1]}`)
      const capacity = int('capacity', f[2], 1)
      const refill = int('refill', f[3], 0)
      const per = int('per', f[4], 1)
      if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], type: 'bucket', capacity, refill, per, st: new Map() })
    } else if (d === 'window') {
      if (f.length !== 4) fail('expected window <name> <limit> <span>')
      if (!NAME.test(f[1])) fail(`invalid policy name ${f[1]}`)
      const limit = int('limit', f[2], 0)
      const span = int('span', f[3], 1)
      if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], type: 'window', limit, span, st: new Map() })
    } else if (d === 'route') {
      if (f.length < 3) fail('expected route <prefix> <policy>...')
      if (!NAME.test(f[1])) fail(`invalid route prefix ${f[1]}`)
      if (routes.has(f[1])) fail(`prefix ${f[1]} is routed twice`)
      const ps = f.slice(2).map((n) => {
        if (!policies.has(n)) fail(`unknown policy ${n}`)
        return policies.get(n)
      })
      routes.set(f[1], ps)
    } else {
      if (f.length !== 3) fail('expected event <tick> <key>')
      const tick = int('tick', f[1], 0)
      if (!NAME.test(f[2])) fail(`invalid key ${f[2]}`)
      if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, tickText: f[1], key: f[2] })
    }
  })
  return { routes, events }
}

function advance(p, key, tick) {
  let s = p.st.get(key)
  if (p.type === 'bucket') {
    if (!s) {
      s = { tokens: p.capacity * p.per, last: tick }
      p.st.set(key, s)
    } else {
      s.tokens += p.refill * (tick - s.last)
      const max = p.capacity * p.per
      if (s.tokens > max) s.tokens = max
      s.last = tick
    }
  } else {
    if (!s) { s = { ticks: [] }; p.st.set(key, s) }
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
  }
}
const allows = (p, key) => {
  const s = p.st.get(key)
  return p.type === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length) < p.limit
}
function record(p, key, tick) {
  const s = p.st.get(key)
  if (p.type === 'bucket') s.tokens -= p.per
  else s.ticks.push(tick)
}

let parsed
try {
  parsed = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}

const { routes, events } = parsed
const prefixes = [...routes.keys()]
let out = ''
const counts = new Map()
let ta = 0, td = 0
for (const ev of events) {
  let best = null
  for (const p of prefixes) if (ev.key.startsWith(p) && (best === null || p.length > best.length)) best = p
  const ps = best === null ? [] : routes.get(best)
  for (const p of ps) advance(p, ev.key, ev.tick)
  const refuser = ps.find((p) => !allows(p, ev.key))
  if (!refuser) for (const p of ps) record(p, ev.key, ev.tick)
  const c = counts.get(ev.key) || { a: 0, d: 0 }
  counts.set(ev.key, c)
  if (refuser) { c.d++; td++ } else { c.a++; ta++ }
  if (mode === 'replay') out += `${ev.tickText} ${ev.key} ${refuser ? 'deny ' + refuser.name : 'allow'}\n`
}
if (mode === 'summary') {
  for (const k of [...counts.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    out += `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}\n`
  }
  out += `total allowed=${ta} denied=${td}\n`
}
process.stdout.write(out)
EOF
node --test test/*.test.js 2>&1 | grep -E "^# (pass|fail)"","description":"Write CLI and run tests"}

