import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(i, reason) { super(reason); this.i = i; this.reason = reason }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)

function scan(src) {
  const cs = Array.from(src)
  const n = cs.length
  const tokens = []
  let i = 0
  const push = (start, kind, body) => tokens.push({ start, kind, body })

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { i++; continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      if (depth > 0) throw new ScanError(start, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      const start = i
      i += 2
      let s = ''
      while (i < n && cs[i] !== '"') s += cs[i++]
      if (i >= n) throw new ScanError(start, 'unterminated string')
      i++
      push(start, 'rawstring', s)
      continue
    }
    if (isIdStart(c)) {
      const start = i
      while (i < n && isIdChar(cs[i])) i++
      const t = cs.slice(start, i).join('')
      push(start, KEYWORDS.has(t) ? 'keyword' : 'ident', t)
      continue
    }
    if (isDigit(c)) {
      const start = i
      const run = (ok) => {
        let count = 0
        while (i < n) {
          if (ok(cs[i])) { i++; count++ }
          else if (cs[i] === '_' && count > 0 && ok(cs[i - 1]) && ok(cs[i + 1])) i++
          else break
        }
        return count
      }
      let bad = false
      const p = (cs[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        i += 2
        const ok = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d >= '0' && d <= '7' && d.length === 1
        if (run(ok) === 0) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { i++; run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) { i++; run(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { i += 2; run(isDigit) }
        }
      }
      if (bad || isIdChar(cs[i])) {
        while (i < n && isIdChar(cs[i])) i++
        throw new ScanError(start, 'invalid number ' + cs.slice(start, i).join(''))
      }
      push(start, 'number', cs.slice(start, i).join(''))
      continue
    }
    if (c === '"') {
      const start = i
      i++
      let s = ''
      for (;;) {
        if (i >= n) throw new ScanError(start, 'unterminated string')
        const d = cs[i]
        if (d === '"') { i++; break }
        if (d === '\n') throw new ScanError(i, 'newline in string')
        if (d !== '\\') { s += d; i++; continue }
        const bs = i
        const e = cs[i + 1]
        if (e === undefined) throw new ScanError(start, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { s += simple[e]; i += 2; continue }
        if (e === 'x' && isHex(cs[i + 2]) && isHex(cs[i + 3])) {
          s += String.fromCodePoint(parseInt(cs[i + 2] + cs[i + 3], 16)); i += 4; continue
        }
        if (e === 'u' && cs[i + 2] === '{') {
          let j = i + 3
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (h.length > 0 && cs[j] === '}') {
            const v = parseInt(h, 16)
            if (v <= 0x10ffff) { s += String.fromCodePoint(v); i = j + 1; continue }
          }
        }
        throw new ScanError(bs, 'invalid escape \\' + e)
      }
      push(start, 'string', s)
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.includes(two)) { push(i, 'punct', two); i += 2; continue }
    if (PUNCT1.includes(c)) { push(i, 'punct', c); i++; continue }
    throw new ScanError(i, 'unexpected character ' + c)
  }
  return { tokens, cs }
}

function positions(cs) {
  const pos = []
  let line = 1
  let col = 1
  for (const c of cs) {
    pos.push([line, col])
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
  }
  pos.push([line, col])
  return pos
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const src = readFileSync(0, 'utf8')
  let result
  try {
    result = scan(src)
  } catch (err) {
    if (!(err instanceof ScanError)) throw err
    const [l, c] = positions(Array.from(src))[err.i]
    process.stderr.write(`error: ${l}:${c}: ${err.reason}\n`)
    process.exit(2)
  }
  let out = ''
  if (args[0] === 'tokens') {
    const pos = positions(result.cs)
    for (const t of result.tokens) {
      const [l, c] = pos[t.start]
      const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.body) : t.body
      out += `${l}:${c} ${t.kind} ${body}\n`
    }
  } else {
    for (const k of KINDS) out += `${k} ${result.tokens.filter((t) => t.kind === k).length}\n`
    out += `total ${result.tokens.length}\n`
  }
  process.stdout.write(out)
}

main()
